const ax = new Axes({ xRange: [-3.5, 3.5, 1], yRange: [0, 0.45, 0.1], xLength: 10, yLength: 4.2, tips: false });
ax.moveTo([0, -0.25, 0]);

function band(lo, hi, color) {
  const vertices = [ax.c2p(lo, 0)];
  for (let i = 0; i <= 50; i++) {
    const x = lo + (hi - lo) * i / 50;
    vertices.push(ax.c2p(x, density(x)));
  }
  vertices.push(ax.c2p(hi, 0));
  const region = new Polygon({ vertices, color });
  region.setFill(color, 0.38);
  region.setStrokeWidth(0);
  return region;
}

const regions = [
  band(-3, -2, PURPLE), band(-2, -1, TEAL), band(-1, 1, BLUE),
  band(1, 2, TEAL), band(2, 3, PURPLE)
];
