const title = new Text({ text: 'The 68–95–99.7 rule', color: WHITE, fontSize: 34 });
title.moveTo([0, 3.25, 0]);

scene.add(...regions, ax);
await scene.play(new Create(curve));
await scene.play(new Write(title));

for (let k = -3; k <= 3; k++) {
  const label = new Text({ text: k === 0 ? 'μ' : `${k > 0 ? '+' : '−'}${Math.abs(k)}σ`, color: GRAY, fontSize: 18 });
  label.moveTo([ax.c2p(k, 0)[0], -2.68, 0]);
  scene.add(label);
}

const legend = [
  { s: '68% within ±1σ', c: BLUE, x: -4.1 },
  { s: '95% within ±2σ', c: TEAL, x: 0 },
  { s: '99.7% within ±3σ', c: PURPLE, x: 4.1 }
];
for (const item of legend) {
  const label = new Text({ text: item.s, color: item.c, fontSize: 22 });
  label.moveTo([item.x, -3.3, 0]);
  scene.add(label);
}

function marker(x) {
  const line = new Polygon({ vertices: [ax.c2p(x, 0), ax.c2p(x, density(x))], color: GOLD });
  line.setStrokeWidth(3);
  line.setFillOpacity(0);
  return line;
}
let leftMarker = marker(-1);
let rightMarker = marker(1);
let readout = new Text({ text: 'Selected: ±1σ → 68%', color: GOLD, fontSize: 24 });
readout.moveTo([0, 2.55, 0]);
scene.add(leftMarker, rightMarker, readout);

const controls = new Controls(scene, { position: 'top-right', width: 220 });
controls.addSlider({ label: 'Standard deviations', min: 1, max: 3, value: 1, step: 1, onChange: val => {
  const k = Math.round(val);
  leftMarker.setVertices([ax.c2p(-k, 0), ax.c2p(-k, density(-k))]);
  rightMarker.setVertices([ax.c2p(k, 0), ax.c2p(k, density(k))]);
